"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";
import { Kbd } from "./kbd";
import { useControllableState, useOutsideClick } from "../lib/hooks";

export interface SearchSuggestion {
  value: string;
  label?: React.ReactNode;
  description?: React.ReactNode;
  icon?: React.ReactNode;
}

export interface SearchFieldProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "value" | "defaultValue" | "onChange" | "onSelect" | "size" | "type"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Uitgevoerd bij Enter of een klik op een voorstel of recente zoekopdracht. */
  onSearch?: (value: string) => void;
  /** Voorstellen onder het veld. */
  suggestions?: Array<SearchSuggestion | string>;
  /** Zelf filteren uitzetten, bv. als de server het al deed. */
  filter?: boolean;
  /** Eerdere zoekopdrachten als chips, met een knop om ze te wissen. */
  recent?: string[];
  onRecentClear?: () => void;
  onRecentSelect?: (value: string) => void;
  /**
   * Sneltoets die in het veld getoond wordt én echt werkt, bv. "Ctrl K" of "⌘ K".
   * Ctrl en ⌘ worden allebei aanvaard, zodat hij op Windows en Mac werkt.
   */
  shortcut?: string;
  /**
   * Begint als rond icoonknopje dat vanuit zichzelf openschuift tot een veld.
   * Escape of een klik ernaast klapt het weer dicht.
   */
  expandable?: boolean;
  /** Breedte in uitgeklapte staat. */
  expandedWidth?: number;
  /** Zwevende deeltjes rond het uitgeklapte veld. */
  particles?: boolean;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  size?: "sm" | "md" | "lg";
  loading?: boolean;
  emptyLabel?: React.ReactNode;
  suggestionsLabel?: React.ReactNode;
  recentLabel?: React.ReactNode;
  clearLabel?: string;
  /** Tekst onder het veld, bv. "Esc om te sluiten". Standaard aan bij expandable. */
  hint?: React.ReactNode | false;
  maxResults?: number;
}

const alsVoorstel = (item: SearchSuggestion | string): SearchSuggestion =>
  typeof item === "string" ? { value: item } : item;

/** Haalt de toets uit "Ctrl K", "⌘K" of "Mod+K": het laatste letter- of cijferteken. */
function toetsUit(sneltoets?: string): string | null {
  if (!sneltoets) return null;
  const tekens = sneltoets.replace(/[^a-z0-9/]/gi, "");
  return tekens ? tekens.slice(-1).toLowerCase() : null;
}

const DEELTJES = [
  { x: "8%", y: "-38%", d: 0 },
  { x: "22%", y: "130%", d: 0.9 },
  { x: "48%", y: "-46%", d: 1.6 },
  { x: "71%", y: "138%", d: 0.4 },
  { x: "88%", y: "-30%", d: 1.2 },
  { x: "96%", y: "112%", d: 2.1 },
];

/**
 * SearchField — zoekveld met voorstellen, recente zoekopdrachten en een
 * werkende sneltoets. Met `expandable` begint het als rond knopje dat vanuit
 * zichzelf openschuift tot een veld.
 */
export const SearchField = React.forwardRef<HTMLInputElement, SearchFieldProps>(function SearchField(
  {
    value,
    defaultValue = "",
    onValueChange,
    onSearch,
    suggestions,
    filter = true,
    recent,
    onRecentClear,
    onRecentSelect,
    shortcut,
    expandable,
    expandedWidth = 340,
    particles = true,
    open,
    defaultOpen,
    onOpenChange,
    size = "md",
    loading,
    emptyLabel = "Niets gevonden",
    suggestionsLabel = "Voorstellen",
    recentLabel = "Recent gezocht",
    clearLabel = "Wissen",
    hint,
    maxResults = 8,
    placeholder = "Zoeken…",
    disabled,
    className,
    style,
    onFocus,
    onBlur,
    ...rest
  },
  ref
) {
  const [tekst, setTekst] = useControllableState<string>({
    value,
    defaultValue,
    onChange: onValueChange,
  });

  /* Bij expandable is "uit" of het veld openstaat; anders staat het altijd open. */
  const [uit, setUit] = useControllableState<boolean>({
    value: open,
    defaultValue: defaultOpen ?? !expandable,
    onChange: onOpenChange,
  });
  const veldOpen = expandable ? uit : true;

  const [paneel, setPaneel] = React.useState(false);
  const [actief, setActief] = React.useState(-1);
  const wikkel = React.useRef<HTMLDivElement>(null);
  const veld = React.useRef<HTMLInputElement>(null);

  const zetRef = (node: HTMLInputElement | null) => {
    (veld as React.MutableRefObject<HTMLInputElement | null>).current = node;
    if (typeof ref === "function") ref(node);
    else if (ref) (ref as React.MutableRefObject<HTMLInputElement | null>).current = node;
  };

  const sluit = React.useCallback(() => {
    setPaneel(false);
    setActief(-1);
    if (expandable) setUit(false);
  }, [expandable, setUit]);

  useOutsideClick([wikkel], sluit, paneel || (expandable && uit));

  /* De sneltoets echt laten werken, niet alleen tonen. */
  const toets = toetsUit(shortcut);
  React.useEffect(() => {
    if (!toets || disabled) return;
    const opToets = (event: KeyboardEvent) => {
      if (!(event.ctrlKey || event.metaKey) || event.key.toLowerCase() !== toets) return;
      event.preventDefault();
      if (expandable) setUit(true);
      window.requestAnimationFrame(() => veld.current?.focus());
    };
    window.addEventListener("keydown", opToets);
    return () => window.removeEventListener("keydown", opToets);
  }, [toets, disabled, expandable, setUit]);

  /* Na het openschuiven meteen de cursor in het veld, als de animatie loopt. */
  React.useEffect(() => {
    if (expandable && uit) {
      const timer = window.setTimeout(() => veld.current?.focus(), 60);
      return () => window.clearTimeout(timer);
    }
  }, [expandable, uit]);

  const lijst = React.useMemo(() => {
    const alle = (suggestions ?? []).map(alsVoorstel);
    const term = tekst.trim().toLowerCase();
    const gefilterd =
      filter && term
        ? alle.filter(
            (item) =>
              item.value.toLowerCase().includes(term) ||
              (typeof item.label === "string" && item.label.toLowerCase().includes(term))
          )
        : alle;
    return gefilterd.slice(0, maxResults);
  }, [suggestions, tekst, filter, maxResults]);

  const recenten = recent ?? [];
  const heeftInhoud = loading || lijst.length > 0 || recenten.length > 0 || Boolean(tekst);
  const toontPaneel = veldOpen && paneel && heeftInhoud;
  const kiesbaar = [...lijst.map((item) => item.value), ...recenten];

  const kies = (waarde: string, uitRecent = false) => {
    setTekst(waarde);
    setActief(-1);
    setPaneel(false);
    if (uitRecent) onRecentSelect?.(waarde);
    onSearch?.(waarde);
  };

  const opToets = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      /* Eerst het paneel, dan de tekst, pas dan het hele veld dicht. */
      if (paneel && heeftInhoud) setPaneel(false);
      else if (tekst) setTekst("");
      else sluit();
      return;
    }
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      if (kiesbaar.length === 0) return;
      event.preventDefault();
      setPaneel(true);
      const stap = event.key === "ArrowDown" ? 1 : -1;
      const grens = kiesbaar.length;
      setActief((vorige) => {
        const volgende = vorige + stap;
        if (volgende < 0) return grens - 1;
        if (volgende >= grens) return 0;
        return volgende;
      });
      return;
    }
    if (event.key === "Enter") {
      event.preventDefault();
      if (actief >= 0 && kiesbaar[actief]) kies(kiesbaar[actief], actief >= lijst.length);
      else if (tekst.trim()) kies(tekst.trim());
    }
  };

  const toonHint = hint !== false && (hint !== undefined || expandable);
  const hintInhoud =
    hint && hint !== true ? (
      hint
    ) : (
      <>
        <Kbd>Esc</Kbd> om te sluiten
      </>
    );

  return (
    <div
      ref={wikkel}
      className={cn(
        "lui-searchfield",
        `lui-searchfield-${size}`,
        expandable && "lui-searchfield-expandable",
        className
      )}
      data-open={veldOpen ? "" : undefined}
      style={
        expandable
          ? ({ ...style, ["--lui-sf-open" as string]: `${expandedWidth}px` } as React.CSSProperties)
          : style
      }
    >
      <div className="lui-searchfield-box" data-panel={toontPaneel ? "" : undefined}>
        {expandable && particles && veldOpen && (
          <span className="lui-searchfield-particles" aria-hidden="true">
            {DEELTJES.map((deeltje, index) => (
              <span
                key={index}
                style={{ left: deeltje.x, top: deeltje.y, animationDelay: `${deeltje.d}s` }}
              />
            ))}
          </span>
        )}

        <button
          type="button"
          className="lui-searchfield-icon"
          tabIndex={expandable && !veldOpen ? 0 : -1}
          onClick={() => {
            if (expandable && !veldOpen) setUit(true);
            else veld.current?.focus();
          }}
          disabled={disabled}
          aria-label={expandable && !veldOpen ? (typeof placeholder === "string" ? placeholder : "Zoeken") : undefined}
          aria-hidden={expandable && !veldOpen ? undefined : true}
          aria-expanded={expandable ? veldOpen : undefined}
        >
          <Icon name="search" size={expandable ? 18 : 16} />
        </button>

        <input
          ref={zetRef}
          type="search"
          className="lui-searchfield-input"
          value={tekst}
          placeholder={placeholder}
          disabled={disabled}
          tabIndex={veldOpen ? 0 : -1}
          autoComplete="off"
          role="combobox"
          aria-expanded={toontPaneel}
          aria-autocomplete="list"
          onChange={(event) => {
            setTekst(event.target.value);
            setActief(-1);
            setPaneel(true);
          }}
          onFocus={(event) => {
            setPaneel(true);
            onFocus?.(event);
          }}
          onBlur={onBlur}
          onKeyDown={opToets}
          {...rest}
        />

        {tekst && (
          <button
            type="button"
            className="lui-searchfield-clear"
            onClick={() => {
              setTekst("");
              veld.current?.focus();
            }}
            aria-label="Zoekterm wissen"
          >
            <Icon name="x" size={14} />
          </button>
        )}
        {shortcut && !expandable && <Kbd className="lui-searchfield-kbd">{shortcut}</Kbd>}
      </div>

      {toonHint && veldOpen && !toontPaneel && <p className="lui-searchfield-hint">{hintInhoud}</p>}

      {toontPaneel && (
        <div className="lui-searchfield-panel" role="listbox">
          {loading && <p className="lui-searchfield-loading">Bezig met zoeken…</p>}

          {!loading && lijst.length > 0 && (
            <div className="lui-searchfield-group">
              <p className="lui-searchfield-grouplabel">{suggestionsLabel}</p>
              <div className="lui-searchfield-options">
                {lijst.map((item, index) => (
                  <button
                    key={item.value}
                    type="button"
                    role="option"
                    aria-selected={actief === index}
                    className="lui-searchfield-option"
                    data-active={actief === index ? "" : undefined}
                    onMouseEnter={() => setActief(index)}
                    onClick={() => kies(item.value)}
                  >
                    {item.icon ?? <Icon name="search" size={14} />}
                    <span className="lui-searchfield-optiontext">
                      <span>{item.label ?? item.value}</span>
                      {item.description && <span className="lui-searchfield-desc">{item.description}</span>}
                    </span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {!loading && lijst.length === 0 && tekst && <p className="lui-searchfield-empty">{emptyLabel}</p>}

          {!loading && recenten.length > 0 && (
            <div className="lui-searchfield-group">
              <div className="lui-searchfield-grouprow">
                <p className="lui-searchfield-grouplabel">{recentLabel}</p>
                {onRecentClear && (
                  <button type="button" className="lui-searchfield-clearall" onClick={onRecentClear}>
                    {clearLabel}
                  </button>
                )}
              </div>
              <div className="lui-searchfield-chips">
                {recenten.map((item, index) => {
                  const plek = lijst.length + index;
                  const gekozen = actief === plek || item === tekst;
                  return (
                    <button
                      key={item}
                      type="button"
                      role="option"
                      aria-selected={actief === plek}
                      className="lui-searchfield-chip"
                      data-active={gekozen ? "" : undefined}
                      onMouseEnter={() => setActief(plek)}
                      onClick={() => kies(item, true)}
                    >
                      <Icon name="clock" size={12} />
                      {item}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {toonHint && <p className="lui-searchfield-hint lui-searchfield-hint-panel">{hintInhoud}</p>}
        </div>
      )}
    </div>
  );
});

/* ============================ SearchField ============================ */
.lui-searchfield {
  --lui-sf-h: calc(42px * var(--density));
  position: relative; width: 100%;
}
.lui-searchfield-sm { --lui-sf-h: calc(34px * var(--density)); font-size: 13px; }
.lui-searchfield-lg { --lui-sf-h: calc(48px * var(--density)); font-size: var(--fs-md); }

.lui-searchfield-box {
  position: relative; display: flex; align-items: center; gap: 8px;
  height: var(--lui-sf-h); padding: 0 8px 0 4px;
  border: 1px solid var(--border-strong); border-radius: var(--r-md);
  background: var(--surface); color: var(--text);
  transition:
    border-color var(--dur-fast), box-shadow var(--dur), transform var(--dur) var(--ease-out),
    width var(--dur-slow) var(--ease-out), padding var(--dur-slow) var(--ease-out),
    border-radius var(--dur-slow) var(--ease-out);
}
.lui-searchfield-box:focus-within {
  border-color: var(--accent);
  box-shadow: var(--ring), 0 8px 22px color-mix(in oklab, var(--accent) 14%, transparent);
  transform: translateY(-1px);
}
.lui-searchfield-box[data-panel] { transform: none; }

.lui-searchfield-icon {
  display: grid; place-items: center; flex: none;
  width: calc(var(--lui-sf-h) - 10px); height: calc(var(--lui-sf-h) - 10px); padding: 0;
  border: 0; border-radius: 50%; background: transparent; color: var(--text-3); cursor: text;
}
.lui-searchfield-box:focus-within .lui-searchfield-icon { color: var(--accent); }

.lui-searchfield-input {
  flex: 1; min-width: 0; border: 0; outline: none; background: transparent;
  color: inherit; font: inherit;
}
.lui-searchfield-input::placeholder { color: var(--text-3); }
.lui-searchfield-input::-webkit-search-cancel-button { display: none; }

.lui-searchfield-clear {
  display: grid; place-items: center; flex: none; width: 24px; height: 24px; padding: 0;
  border: 0; border-radius: 50%; background: transparent; color: var(--text-3); cursor: pointer;
}
.lui-searchfield-clear:hover { background: var(--surface-3); color: var(--text); }
.lui-searchfield-clear:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-searchfield-kbd { flex: none; }

/* ---------- uitklapbaar: het rondje schuift open tot een veld ---------- */
.lui-searchfield-expandable { width: auto; display: inline-block; }
.lui-searchfield-expandable .lui-searchfield-box {
  width: calc(var(--lui-sf-h) + 4px); padding: 0; overflow: visible;
  border-color: var(--accent); border-radius: 999px;
  justify-content: center; gap: 0;
}
.lui-searchfield-expandable .lui-searchfield-icon {
  width: 100%; height: 100%; color: var(--accent); cursor: pointer;
}
.lui-searchfield-expandable .lui-searchfield-icon:hover:not(:disabled) {
  background: color-mix(in oklab, var(--accent) 9%, transparent);
}
.lui-searchfield-expandable .lui-searchfield-icon:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-searchfield-expandable .lui-searchfield-input { width: 0; flex: 0 0 0; opacity: 0; padding: 0; }

.lui-searchfield-expandable[data-open] .lui-searchfield-box {
  width: var(--lui-sf-open); padding: 0 8px 0 4px; justify-content: flex-start; gap: 8px;
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--accent) 12%, transparent),
    0 10px 28px color-mix(in oklab, var(--accent) 18%, transparent);
}
.lui-searchfield-expandable[data-open] .lui-searchfield-icon {
  width: calc(var(--lui-sf-h) - 10px); height: calc(var(--lui-sf-h) - 10px); cursor: text;
}
.lui-searchfield-expandable[data-open] .lui-searchfield-icon:hover { background: transparent; }
.lui-searchfield-expandable[data-open] .lui-searchfield-input {
  flex: 1; width: auto; opacity: 1;
  transition: opacity var(--dur) var(--ease) .12s;
}

/* zwevende deeltjes rond het open veld */
.lui-searchfield-particles { position: absolute; inset: 0; pointer-events: none; }
.lui-searchfield-particles > span {
  position: absolute; width: 5px; height: 5px; border-radius: 50%;
  background: var(--accent); opacity: 0;
  animation: lui-sf-float 3.2s var(--ease) infinite;
}
.lui-searchfield-particles > span:nth-child(even) { width: 4px; height: 4px; }
@keyframes lui-sf-float {
  0% { opacity: 0; transform: translateY(6px) scale(.6); }
  25% { opacity: .55; }
  70% { opacity: .35; }
  100% { opacity: 0; transform: translateY(-12px) scale(1); }
}

/* ---------- hint onder het veld ---------- */
.lui-searchfield-hint {
  display: flex; align-items: center; justify-content: center; gap: 6px;
  margin: 8px 0 0; font-size: var(--fs-xs); color: var(--text-3);
  animation: lui-sf-fade var(--dur) var(--ease-out);
}
.lui-searchfield-hint-panel { margin: 2px 0 0; padding-top: 8px; border-top: 1px solid var(--border); }

/* ---------- paneel ---------- */
.lui-searchfield-panel {
  position: absolute; inset-inline: 0; top: calc(100% + 8px); z-index: var(--z-popover);
  display: grid; gap: 12px; padding: 10px;
  border: 1px solid var(--border); border-radius: var(--r-md);
  background: var(--surface); box-shadow: var(--sh-lg);
  animation: lui-sf-panel var(--dur-fast) var(--ease-out);
}
.lui-searchfield-expandable .lui-searchfield-panel { width: var(--lui-sf-open); }

.lui-searchfield-group { display: grid; gap: 4px; }
.lui-searchfield-grouprow { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.lui-searchfield-grouplabel {
  margin: 0; padding: 0 6px;
  font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--text-3);
}
.lui-searchfield-clearall {
  border: 0; background: transparent; color: var(--accent);
  font: inherit; font-size: 12px; font-weight: 600; cursor: pointer;
}
.lui-searchfield-clearall:hover { text-decoration: underline; }
.lui-searchfield-clearall:focus-visible { outline: none; box-shadow: var(--ring); }

.lui-searchfield-options { display: grid; max-height: 220px; overflow-y: auto; }
.lui-searchfield-option {
  display: flex; align-items: center; gap: 9px; width: 100%;
  padding: 8px 9px; border: 0; border-radius: var(--r-sm);
  background: transparent; color: var(--text); font: inherit; font-size: var(--fs-sm);
  text-align: start; cursor: pointer;
}
.lui-searchfield-option[data-active] { background: color-mix(in oklab, var(--accent) 9%, transparent); }
.lui-searchfield-option > svg { flex: none; color: var(--text-3); }
.lui-searchfield-option[data-active] > svg { color: var(--accent); }
.lui-searchfield-optiontext { display: grid; gap: 1px; min-width: 0; }
.lui-searchfield-desc { font-size: 12px; color: var(--text-3); }

.lui-searchfield-chips { display: flex; flex-wrap: wrap; gap: 6px; padding: 2px 6px 0; }
.lui-searchfield-chip {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 4px 11px; border: 1px solid var(--border); border-radius: var(--r-full);
  background: var(--surface-2); color: var(--text-2); font: inherit; font-size: 12.5px; cursor: pointer;
  transition: background var(--dur-fast), color var(--dur-fast), border-color var(--dur-fast);
}
.lui-searchfield-chip:hover, .lui-searchfield-chip[data-active] {
  background: var(--accent); border-color: var(--accent); color: var(--accent-fg);
}
.lui-searchfield-chip:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-searchfield-chip > svg { opacity: .7; }

.lui-searchfield-loading, .lui-searchfield-empty {
  margin: 0; padding: 10px 4px; text-align: center; font-size: var(--fs-sm); color: var(--text-3);
}

@keyframes lui-sf-panel { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
@keyframes lui-sf-fade { from { opacity: 0; } to { opacity: 1; } }

@media (prefers-reduced-motion: reduce) {
  .lui-searchfield-box, .lui-searchfield-panel, .lui-searchfield-hint { transition: none; animation: none; }
  .lui-searchfield-box:focus-within { transform: none; }
  .lui-searchfield-particles { display: none; }
}
